HERE = os.path.dirname(os.path.abspath(__file__))
total = 0
for name in sorted(FILES):
    text = open(os.path.join(ROOT, SRC + name)).read()
    lst = FILES[name]
    for x in lst:
        if text.count(x['old']) != 1:
            raise SystemExit('%s %s: pattern occurs %d times' % (name, x['id'], text.count(x['old'])))
        x['file'] = SRC + name
    out = os.path.join(HERE, '1b7c_%s_listed.json' % os.path.basename(name)[:-3].lower())
    if os.path.exists(out) and '--force' not in sys.argv:
        print('exists, not rewritten:', out)
        continue
    json.dump(lst, open(out, 'w'), indent=1)
    total += len(lst)
    print(name, len(lst))
print('mutants written:', total)
